1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export type Step = QuoteStep | ClaimStep;
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Item {
18	  type: string;
19	  material?: string;
20	  enchantment?: number;
21	  cursed?: boolean;
22	}
23	
24	export interface ClaimStep {
25	  op: "claim";
26	  policy: number;
27	  incident: Incident;
28	}
29	
30	export interface Incident {
31	  cause: string;
32	  damages: Damage[];
33	}
34	
35	export interface Damage {
36	  itemType: string;
37	  amount: number;
38	}
39	
40	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
41	
42	export interface ScenarioResult {
43	  results: StepResult[];
44	}
45	
46	const PROCESSING_FEE = 5;
47	
48	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
49	  sword: 100,
50	  staff: 80,
51	  amulet: 60,
52	  potion: 40,
53	  rune: 25,
54	  moonstone: 25,
55	};
56	
57	const FIRST_INSURANCE_PERCENT = 10;
58	
59	// Surcharges are applied as (amount * percent) / 100 rather than via a decimal
60	// multiplier (e.g. * 1.1): the integer intermediate is exact, whereas 100 * 1.1
61	// is 110.00000000000001 in binary floating point. Since the final amount feeds
62	// straight into Math.ceil, that error would round a 115 G premium up to 116 G.
63	const percentOf = (amount: number, percent: number): number =>
64	  (amount * percent) / 100;
65	
66	const itemBasePremium = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
67	
68	const BLOCK_SIZE = 3;
69	const BLOCK_BASE_PREMIUM = 60;
70	
71	const sumItemBasePremiums = (items: Item[]): number =>
72	  items.reduce((sum, item) => sum + itemBasePremium(item), 0);
73	
74	/** Items of one and the same type, e.g. the three runes that form a block. */
75	type TypeGroup = Item[];
76	
77	const groupByType = (items: Item[]): TypeGroup[] => [
78	  ...items
79	    .reduce(
80	      (groups, item) =>
81	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
82	      new Map<string, TypeGroup>(),
83	    )
84	    .values(),
85	];
86	
87	const formsBlock = (group: TypeGroup): boolean => group.length === BLOCK_SIZE;
88	
89	const groupBasePremium = (group: TypeGroup): number =>
90	  formsBlock(group) ? BLOCK_BASE_PREMIUM : sumItemBasePremiums(group);
91	
92	const policyBasePremium = (items: Item[]): number =>
93	  groupByType(items).reduce((sum, group) => sum + groupBasePremium(group), 0);
94	
95	const CURSE_PERCENT = 50;
96	const HIGH_ENCHANTMENT_PERCENT = 30;
97	const HIGH_ENCHANTMENT_THRESHOLD = 5;
98	
99	/**
100	 * A modifier adjusts a base premium by `percent` when it `applies` to its
101	 * subject. Discounts are expressed as negative percentages, so that the
102	 * applicable rules of one scope always combine by summation.
103	 */
104	interface ModifierRule<Subject> {
105	  applies: (subject: Subject) => boolean;
106	  percent: number;
107	}
108	
109	const applicablePercent = <Subject>(
110	  rules: ModifierRule<Subject>[],
111	  subject: Subject,
112	): number =>
113	  rules.reduce(
114	    (percent, rule) => (rule.applies(subject) ? percent + rule.percent : percent),
115	    0,
116	  );
117	
118	/**
119	 * Item-scoped modifiers apply to the affected item's own base premium, not to
120	 * the policy total.
121	 */
122	const ITEM_MODIFIER_RULES: ModifierRule<Item>[] = [
123	  { applies: (item) => item.cursed === true, percent: CURSE_PERCENT },
124	  {
125	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
126	    percent: HIGH_ENCHANTMENT_PERCENT,
127	  },
128	];
129	
130	const itemSurcharge = (item: Item): number =>
131	  percentOf(itemBasePremium(item), applicablePercent(ITEM_MODIFIER_RULES, item));
132	
133	const totalItemSurcharges = (items: Item[]): number =>
134	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
135	
136	const LOYALTY_DISCOUNT_PERCENT = -20;
137	const LOYALTY_THRESHOLD_YEARS = 2;
138	const FOLLOW_UP_DISCOUNT_PERCENT = -15;
139	
140	/**
141	 * Everything a single step needs to know about the scenario around it: the
142	 * customer, how many quotes preceded this step, and the steps themselves (a
143	 * claim resolves its policy by index). Not the policy itself — it carries no
144	 * items, insurance sum or cap.
145	 */
146	interface PolicyContext {
147	  customer: Customer;
148	  precedingQuoteCount: number;
149	  steps: Step[];
150	}
151	
152	/**
153	 * Policy-scoped modifiers apply to the policy base premium (the sum of all
154	 * item base premiums), independently of any item-scoped surcharges.
155	 */
156	const POLICY_MODIFIER_RULES: ModifierRule<PolicyContext>[] = [
157	  { applies: () => true, percent: FIRST_INSURANCE_PERCENT },
158	  {
159	    applies: ({ customer }) =>
160	      customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS,
161	    percent: LOYALTY_DISCOUNT_PERCENT,
162	  },
163	  {
164	    applies: ({ precedingQuoteCount }) => precedingQuoteCount > 0,
165	    percent: FOLLOW_UP_DISCOUNT_PERCENT,
166	  },
167	];
168	
169	const quotePremium = (step: QuoteStep, context: PolicyContext): number => {
170	  const basePremium = policyBasePremium(step.items);
171	  return Math.ceil(
172	    basePremium +
173	      percentOf(basePremium, applicablePercent(POLICY_MODIFIER_RULES, context)) +
174	      totalItemSurcharges(step.items) +
175	      PROCESSING_FEE,
176	  );
177	};
178	
179	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
180	  sword: 1000,
181	  staff: 800,
182	  amulet: 600,
183	  potion: 400,
184	  rune: 250,
185	  moonstone: 250,
186	};
187	
188	const DEDUCTIBLE = 100;
189	const CAP_MULTIPLE = 2;
190	
191	const insuranceSum = (items: Item[]): number =>
192	  items.reduce((sum, item) => sum + INSURANCE_VALUE_BY_TYPE[item.type], 0);
193	
194	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
195	const HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
196	
197	/** The share of a damage amount the MHPCO reimburses before the deductible. */
198	const reimbursementPercent = (item: Item): number =>
199	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD
200	    ? HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT
201	    : 100;
202	
203	const damagePayout = (damage: Damage, damagedItem: Item): number =>
204	  percentOf(damage.amount, reimbursementPercent(damagedItem)) - DEDUCTIBLE;
205	
206	const claimResult = (step: ClaimStep, insuredItems: Item[]): StepResult => {
207	  const cap = CAP_MULTIPLE * insuranceSum(insuredItems);
208	  const payout = Math.floor(
209	    step.incident.damages.reduce(
210	      (sum, damage) =>
211	        sum +
212	        damagePayout(
213	          damage,
214	          insuredItems.find((item) => item.type === damage.itemType)!,
215	        ),
216	      0,
217	    ),
218	  );
219	  return { payout, remainingCap: cap - payout };
220	};
221	
222	/**
223	 * The policy a claim refers to. A `policy` index is only meaningful if it
224	 * points at a quote step, so the lookup narrows rather than casts; the
225	 * `undefined` case is left for the error-handling tests to give meaning.
226	 */
227	const policyAt = (steps: Step[], index: number): QuoteStep | undefined => {
228	  const step = steps[index];
229	  return step?.op === "quote" ? step : undefined;
230	};
231	
232	const runStep = (step: Step, context: PolicyContext): StepResult => {
233	  if (step.op === "quote") return { premium: quotePremium(step, context) };
234	  return claimResult(step, policyAt(context.steps, step.policy)?.items ?? []);
235	};
236	
237	const countQuotes = (steps: Step[]): number =>
238	  steps.filter((step) => step.op === "quote").length;
239	
240	export const runScenario = (scenario: Scenario): ScenarioResult => ({
241	  results: scenario.steps.map((step, index) =>
242	    runStep(step, {
243	      customer: scenario.customer,
244	      precedingQuoteCount: countQuotes(scenario.steps.slice(0, index)),
245	      steps: scenario.steps,
246	    }),
247	  ),
248	});
