/**
 * The insured item a damage entry refers to. A damage may name a type the
 * policy does not cover at all — the `undefined` case is left for the
 * error-handling tests to give meaning.
 */
const damagedItem = (insuredItems: Item[], damage: Damage): Item | undefined =>
  insuredItems.find((item) => item.type === damage.itemType);

const totalPayout = (damages: Damage[], insuredItems: Item[]): number =>
  Math.floor(
    damages.reduce(
      (sum, damage) => sum + damagePayout(damage, damagedItem(insuredItems, damage)!),
      0,
    ),
  );

const claimResult = (step: ClaimStep, insuredItems: Item[]): StepResult => {
  const cap = CAP_MULTIPLE * insuranceSum(insuredItems);
  const payout = totalPayout(step.incident.damages, insuredItems);
  return { payout, remainingCap: cap - payout };
};
